"""Rebuild the chapter's author revision from its immutable batch baseline."""
from pathlib import Path
import html
import re
ROOT=Path(__file__).resolve().parents[2]
s=(ROOT/'docs/reviews/ch43-ch44-ch45-baseline/ch44.html').read_text()

def bi(zh,en):
    return '<div class="bilingual"><div class="lang-zh">'+zh+'</div><div class="lang-en">'+en+'</div></div>'
def heading(zh,en): return '<h3><span class="lang-zh">'+zh+'</span><span class="lang-en">'+en+'</span></h3>'
def code(file,label,kind,region=None):
    text=(ROOT/'examples/ch44'/file).read_text()
    if region: text=text.split('// BEGIN '+region+'\n')[1].split('  // END '+region)[0]; text='\n'.join(x[2:] if x.startswith('  ') else x for x in text.splitlines())+'\n'
    return '<pre data-language="'+label+'" data-kind="'+kind+'" data-source="'+file+'"'+(' data-region="'+region+'"' if region else '')+'><code>'+html.escape(text.rstrip())+'</code></pre>'

def replace_content(id,body):
    global s
    pattern=r'(<section id="'+id+r'">.*?</figure>).*?(</section>)'
    s=re.sub(pattern,lambda m:m[1]+'\n'+body+m[2],s,flags=re.S)

# One reading entry replaces duplicated goals and long opening.
sections=re.findall(r'<section.*?</section>',s,re.S)
intro='<section class="goal"><h2><span class="lang-zh">本章核心：边界、调用额度与业务结果</span><span class="lang-en">Core: ownership, call budgets, and business outcomes</span></h2>'+bi('''<ul><li><strong>先找所有者。</strong>发布和资源池确需独立才拆服务；必须同事务的规则留在同一边界。</li><li><strong>沿请求扣额度。</strong>发现只给候选；调用方负责死线、有限重试、熔断和在途上限。</li><li><strong>超时不改写事实。</strong>持久受理、付款、履约是不同结果；用稳定 K 恢复未知提交。</li></ul><p>场景是订单系统：Order 管订单意图与状态，Search 管派生索引，Effect Worker 只改自己的积分库。A2 允许先持久 ACCEPTED 再履约。第五组另用只读库存查询讲调用预算；库存预占与支付状态机见 <a href="ch18.html">Ch18</a> / <a href="ch24.html">Ch24</a>。</p>''','''<ul><li><strong>Find the owner.</strong> Extract for concrete release or resource-pool needs; keep transactional invariants together.</li><li><strong>Spend one call budget.</strong> Discovery gives candidates. The caller owns deadline, bounded retry, breaker and in-flight limits.</li><li><strong>Timeout does not rewrite facts.</strong> Durable acceptance, payment and fulfillment differ. Recover unknown commits through stable K.</li></ul><p>Order owns intent/state, Search a derived index, and Effect Worker local points. A2 permits durable ACCEPTED before fulfillment. Deck five is a separate read-only stock API. See <a href="ch18.html">Ch18</a> / <a href="ch24.html">Ch24</a> for reservations and payment state machines.</p>''')+'</section>'
s=s.replace(sections[0],intro).replace(sections[1],'')
# Fold the existing complete assumptions rather than restating them everywhere.
a=sections[2];a=a.replace('</h2>','</h2><details><summary><span class="lang-zh">展开 A1–A12：全部数字都是教学假设</span><span class="lang-en">Expand A1–A12: all numbers are teaching assumptions</span></summary>',1).replace('</section>','</details></section>')
s=s.replace(sections[2],a)
replace_content('split',bi('''<p><strong>先验证模块接口，再抽部署。</strong>图一的 Order 可以仍在单体里：只有它能写订单表，订单、幂等结果和 outbox 归同一个本地事务。Search 的独立发布节奏与重建扫描资源池（A1）解释了拆分收益；代价是事件滞后、重建和跨服务定位。服务按业务能力让接口到数据有同一所有者，不按 Controller / Service / DAO 分成三队。微服务的独立部署特征与业务能力边界见原文 <a href="#ref-1">[1]</a>。</p><p>正常路径 Client → Order → Order DB 提交后逐跳返回；Reader → Search → Search DB 读派生索引。Search 不在受理同步链，因此索引重建失败不妨碍接单，搜索缺失也不等于订单不存在。若变化总跨两个模块、事务总锁两侧，就应重新选边界。模块化单体也能多实例扩展。</p><p>独立 schema、写凭据与迁移责任可在同一物理集群形成逻辑所有权，CPU、磁盘和故障域仍共享；两个物理库也可能被跨库直写和锁步发版耦合。边界要用独立构建/回滚、契约维护与具体故障验证，不能只数进程。</p>''','''<p><strong>Test module APIs before extracting deployment.</strong> Order may still be inside a monolith: it exclusively writes orders and owns the local order/result/outbox transaction. A1 release cadence and search rebuild pools motivate extraction, with event lag, rebuild and diagnosis costs. Give one capability an owner from API to data rather than deploying Controller/Service/DAO as three teams. The original description covers independent deployment and business capability seams. <a href="#ref-1">[1]</a></p><p>Client → Order → Order DB commits and returns hop by hop. Reader → Search → Search DB queries derived data. Search is absent from acceptance, so rebuild failure does not block intake, and a missing index does not prove a missing order. Reconsider seams that constantly require coupled changes or transactions. A modular monolith can also scale horizontally.</p><p>Separate schemas, write credentials and migrations can establish logical ownership on shared hardware, while CPU/disk/failures remain shared. Separate stores can still be coupled by direct writes and lockstep releases. Verify independent builds/rollback, contracts and actual failure behavior instead of counting processes.</p>'''))
replace_content('sync',bi('''<p><strong>A2 的成功是持久 ACCEPTED。</strong>POST 创建订单资源、返回 order_id 与 operation_id，因此可返回 201；若只接收异步任务而未创建订单，202 与状态查询资源更合适。HTTP 状态依据 RFC 9110，后续拒绝与付款状态由业务合同决定 <a href="#ref-14">[14]</a>。前端收到受理不能显示“付款成功”。</p><p>Gateway 验入口身份和流量，Order 验租户/对象权限并决定业务变更；内部调用同样要验对象权限 <a href="#ref-11">[11]</a>。图二同步链是 Client → Gateway → Order → Order DB，持久提交逐跳回来。第六组代码展开订单、K、结果与 outbox 的事务；ACK 丢失则查同 K，不能新建一个意图。</p><p>把允许晚到的积分、索引、通知移出同步链。必须当场确认库存或支付时，应把该依赖加回关键路径；“还有货”的只读查询不是预占。登录验证码若是当前合同的必要结果，也不能只因它叫“邮件”就一律异步。必须同订单提交的审计意图可先同事务持久化。</p><p>A11 五个实际 80 ms 分支，串行 400 ms，真正并行的理想关键路径约 80 ms 加开销；分支 P99 的和或最大值都不能证明整体 P99。A3 的稳定窗口平均在途为 200/s×0.1s=20，只覆盖受理，不是硬并发上限。排队、相关故障和尾延迟仍须测全链。</p>''','''<p><strong>A2 success means durable ACCEPTED.</strong> POST creates an order resource with order_id/operation_id, so 201 is appropriate. Task acceptance before order creation would use 202 and a status resource. RFC 9110 defines the HTTP meanings; later rejection/payment states follow the business contract. <a href="#ref-14">[14]</a> The UI must not show paid after acceptance.</p><p>Gateway verifies ingress identity/admission; Order authorizes tenant/object access and owns mutation. Internal callers also require object checks. <a href="#ref-11">[11]</a> Deck two commits Client → Gateway → Order → Order DB and returns hop by hop. Deck six implements the order/K/result/outbox transaction; lost ACK requires recovery through K.</p><p>Defer points, indexes and notifications when the contract permits. Immediate stock/payment confirmation needs the required dependency on the synchronous path; a stock read is not a reservation. A login code may be required now despite being email. Audit intent required at commit can be stored in the order transaction.</p><p>A11 five actual 80 ms branches take 400 ms serially or ideally ~80 ms plus overhead in parallel. Neither summing nor maximizing branch P99s proves whole-request P99. A3 gives mean in-flight acceptance 200/s×0.1s=20 in a stable window, not a hard concurrency cap. Measure queueing, correlated failures and full-path tails.</p>'''))
replace_content('async',bi('''<p><strong>先保存意图，再分别确认投递与消费。</strong>Order 事务提交订单与 outbox；Relay 扫描待办，发 e17 到 Events，拿 Broker ACK 后才标已发布。进程在 commit 后、内存 publish 前崩溃会丢事件，反过来先 publish 则可能处理未存在的订单；本地事务解决这个双写窗口，不能把 DB 与 Broker 变成同一事务 <a href="#ref-2">[2]</a>。ACK 丢失会重复投递，事件 ID 保持不变。</p><p>图三的消费者只改自己的积分。以下伪码把唯一 <code>(tenant,consumer,event_id)</code> inbox 与积分更新放同一库事务；身份列显式 NOT NULL 且非空。同 ID 改 payload 隔离冲突，不静默 ACK。真实 schema 与绑定参数适配器在 <a href="../examples/ch44/schema.sql">schema.sql</a> / <a href="../examples/ch44/check_transactions.py">check_transactions.py</a>；SQLite 本地事务验证不冒充 PostgreSQL 并发协议。</p>''','''<p><strong>Persist intent, then acknowledge publication and consumption separately.</strong> Order commits order/outbox. Relay scans pending e17, publishes to Events, and marks published only after broker ACK. Commit-then-memory-publish can lose events; publish-before-commit can expose nonexistent orders. A local transaction closes that dual-write window without making DB and broker atomic. <a href="#ref-2">[2]</a> Lost ACK can repeat publication with the same event ID.</p><p>Deck three changes only local points. This pseudocode commits unique <code>(tenant,consumer,event_id)</code> inbox and points together, with explicit NOT NULL/nonempty identity columns. Changed payload for one ID is quarantined without silent ACK. See <a href="../examples/ch44/schema.sql">schema.sql</a> / <a href="../examples/ch44/check_transactions.py">check_transactions.py</a> for schema/bound SQL. SQLite local transaction checks do not prove PostgreSQL concurrency behavior.</p>''')+code('consume.pseudo','Pseudocode · inbox','pseudocode')+bi('''<p>commit 前崩溃，两项都回滚；commit 后、ACK 前崩溃，重投命中 inbox，积分不再增加。示例永久保留 inbox，清理需另订最晚重放合同。外部邮件不在这个事务里：先发再记可能重复，先记再发可能漏发；要靠外部稳定键与原子执行/查询合同，或接受重复并对账。</p><p>A4 原始事件流是 200×1 KB=200 KB/s（十进制，副本另算）；停消费 180s 积压 36,000 条=36 MB。恢复 300/s 但仍进 200/s，净下降 100/s，需 360s；只有 200/s 则永远追不平。受理积压逼近持久存储上限时应收紧准入。</p>''','''<p>A pre-commit crash rolls both changes back; a post-commit/pre-ACK crash replays into the inbox without more points. This example retains inbox records; cleanup requires a maximum replay contract. Email lies outside this transaction: send-before-record can duplicate, record-before-send can lose delivery. It needs external stable identity with atomic execution/query, or accepted duplicates and reconciliation.</p><p>A4 raw events are 200×1 KB=200 KB/s, decimal and before replicas. A 180s outage accumulates 36,000 events=36 MB. Recovery consumes 300/s while 200/s still arrives: 100/s net, 360s to catch up. At 200/s it never catches up. Tighten intake before durable obligations exhaust storage.</p>'''))
replace_content('discovery',bi('''<p><strong>上方控制面给候选，下方数据面直接调用。</strong>实例加载依赖后 READY，Registry 记录成员、地址、健康与版本；Caller 获取快照，从兼容候选挑 A，直接 RPC，回复 A → Caller → Client。Registry 不代理业务字节。Consul 的发现文档与 Health API 支持此区分；只取全 passing 实例须显式请求 <code>passing=true</code>（默认 false）<a href="#ref-3">[3]</a><a href="#ref-4">[4]</a>。</p><p>A5 检查间隔 2s、连续失败 3 次和传播 1s，粗略预算 3×2+1=7s；检查耗时与调度抖动另加。A 可在两次检查之间死亡，本地 timeout/ejection 比等目录更新更快，但调用方网络故障不能永久删全局实例。注册表失联仍可在 5s 快照年龄帽内沿用合格候选；过期无批准的健康池则拒绝新 dispatch。重启读磁盘不能刷新接收时间，长连接也须有寿命/探测/撤销策略。</p><p>已有 DNS、虚拟地址或服务端负载均衡能满足要求就复用；headless 记录、TTL 与连接复用影响摘除速度，不由“DNS”一词决定。发现管成员/健康，Ch28 的配置管超时、灰度与开关；同一产品可承载两者，合同要分清。找到 B 只解决地址，剩余死线、操作可重复性和熔断仍决定能否调用。</p>''','''<p><strong>The control plane supplies candidates; the data plane calls directly.</strong> An instance reports READY after loading dependencies. Registry records membership/address/health/version. Caller selects compatible A and calls it directly; replies return A → Caller → Client. Registry does not proxy RPC bytes. Consul documents this discovery role; the Health API requires explicit <code>passing=true</code> for all-passing nodes (default false). <a href="#ref-3">[3]</a><a href="#ref-4">[4]</a></p><p>A5 checks every 2s, requires three failures, and budgets 1s propagation: roughly 7s plus check duration/jitter. A can die between checks. Local timeout/ejection responds sooner, but caller network failure should not permanently remove global membership. Registry outage permits qualified snapshots only within five seconds; expired snapshots without an approved healthy pool reject new dispatch. Disk reload must not refresh receive time, and persistent connections need age/probe/revocation rules.</p><p>Reuse DNS, virtual addresses or server-side balancing when adequate. Headless records, TTL and connection reuse affect ejection, not the name DNS alone. Discovery owns membership/health; Ch28 configuration owns timeout/canary/flags. One product may host both with different contracts. Finding B supplies an address, not permission to ignore deadline, repeatability or breaker admission.</p>'''))
replace_content('deadline',bi('''<p><strong>所有等待扣同一份时间。</strong>第五组是独立只读库存 API，沿用 800ms 总死线；gRPC 默认不设置 deadline，传播时扣已耗时，服务应用负责停止派生工作 <a href="#ref-5">[5]</a><a href="#ref-6">[6]</a>。线程调度、发现等待、DNS、连接、远端排队与处理都在预算里。各进程用单调时钟计算本地剩余时间，跨进程传剩余量，不直接比较两台机器的单调时间戳。</p><p>A6 计划阶段帽 80+220+40+220+140=700ms，距 800ms 留 100ms，<strong>不是 P99 相加，也不是硬实时保证</strong>。排队/晚醒可能消耗余量，必须重算。下列伪码设最小有用 attempt 为教学 100ms、最大 220ms、预留完成回程 140ms；只剩 250ms 再退避 40ms 就只余 70ms，停止。唤醒及 worker 实际发 I/O 前再核同一绝对 attempt_end，不能把每个阶段重置成 220ms。</p>''','''<p><strong>Charge every wait to one budget.</strong> Deck five is a separate read-only stock API with an 800ms deadline. gRPC sets no deadline by default, deducts elapsed time during propagation, and leaves spawned-work cancellation to the server application. <a href="#ref-5">[5]</a><a href="#ref-6">[6]</a> Include scheduling, discovery, DNS, connect, remote queue and processing. Use local monotonic time and propagate remaining duration, never compare machines’ monotonic timestamps.</p><p>A6 planned stage caps total 700ms, leaving 100ms under 800. <strong>This is neither summed P99s nor a hard real-time guarantee.</strong> Queueing/late wakeups can spend the slack. This pseudocode uses a teaching 100ms useful minimum, a 220ms attempt cap and 140ms finish/return reserve. With 250ms remaining and 40ms backoff, only 70ms remains: stop. Recheck on wakeup and in the actual I/O worker against the same absolute attempt_end; never reset each phase to 220ms.</p>''')+code('retry.pseudo','Pseudocode · retry','pseudocode')+bi('''<p>外部契约要落地：<code>inventory_read_once</code> 是一次无自动重试的适配器；网络错误转成依赖 FAILURE，额度/解析/SDK 等意外本地异常记 IGNORED。worker 的检查、额度与I/O全部在外层 try/catch/finally 内，finally统一补finish并归还已终止槽，不能漏半开探针。Future 等待超时不代表底层退出，代码保守停止补调，槽位直到本地 I/O 真结束才归还；远端仍可能继续，需要它自己的准入与幂等。</p><p><code>spend_once</code> 最多等10ms且不得超过 attempt_end−100ms，须遵守取消；未知/拒绝不发Inventory，也不补查重试额度，已扣令牌可浪费。返回后再核临发时间。它必须由所有调用实例共用的权威原子限额实现：本例以权威时间的一秒固定窗口，条件递增 <code>used&lt;20</code>，失败/不可达即不补调；不是每台本地 20/s。A7 每秒 200 个原始请求加最多 20 次补调，按该窗口共 220 次准入。固定窗口交界可短时集中，严格滑动合同另见 Ch04；这是准入计数，不承诺物理网络发送严格匀速。已消费令牌但临发过期可浪费，不能超发。</p><p>五层每层三次总 attempt 最坏 3⁵=243 次；本例两次总 attempt 由 Order 一个 owner 控制。次数、时间与额外流量都要封顶，鉴权/参数/业务冲突不重试；AWS 同样要求只选一个重试层、限次数并退避+jitter <a href="#ref-12">[12]</a>。退避没有增加容量。</p>''','''<p>The adapter contract matters: <code>inventory_read_once</code> performs one call with automatic retries disabled. Network errors become dependency FAILURE; unexpected quota/parse/SDK errors are IGNORED. One outer try/catch/finally covers checks, quota and I/O, with a once-only finish fallback and terminal slot release. Future timeout does not prove transport termination: the loop conservatively stops, holding its slot until local I/O ends. Remote work may continue and needs its own admission/idempotency.</p><p><code>spend_once</code> waits at most 10ms and never past attempt_end−100ms, honors cancellation, and treats unknown/denied as no Inventory dispatch. Do not retry an unknown quota debit; a token may be wasted. Recheck time afterward. It needs one atomic authority across all caller instances: in this example a conditional <code>used&lt;20</code> increment in authority-time fixed one-second windows. Failure/unavailability denies retry; it is not 20/s per process. A7 admits 200 originals plus at most 20 extras per window. Window boundaries may cluster calls; strict rolling limits belong in Ch04. This counts admission, not perfectly paced physical sends. An expired dispatch may waste a token safely.</p><p>Five layers with three total attempts each can yield 3⁵=243 deepest calls. Here Order alone owns two total attempts. Bound count, time and aggregate extras; authorization/input/conflict errors are terminal. AWS likewise recommends one retry layer, caps and backoff/jitter. <a href="#ref-12">[12]</a> Backoff does not create capacity.</p>''')+heading('调用方熔断：OPEN 拒绝，HALF_OPEN 只试一次','Caller breaker: OPEN rejects, HALF_OPEN probes once')+bi('''<p>在 Order → Inventory 这条依赖上设一个<strong>进程内</strong>熔断器。连续三次被观测的依赖失败后 OPEN 一秒，拒绝新调用；冷却后 HALF_OPEN 只放一个探针，成功 CLOSED，失败或未派发则重新冷却。3 次/1 秒是本章教学值；它不控制所有实例的总流量，也不能撤销在途请求。模式依据 <a href="#ref-13">[13]</a>，以下是同源 Java17 可运行示例的状态片段。</p>''','''<p>Put a <strong>process-local</strong> breaker on Order → Inventory. Three observed dependency failures open it for one second. After cooldown, HALF_OPEN admits one probe: success closes, failure or abandoned dispatch cools again. Three/one-second are teaching values. This neither caps all caller instances nor revokes in-flight calls. The pattern is documented in <a href="#ref-13">[13]</a>; this state machine is extracted from the runnable Java17 example.</p>''')+code('ServiceGovernance.java','Java 17 · breaker','runnable','breaker')+bi('''<p>所有状态转换与时钟观察在同一锁内；I/O 不在锁内。Ticket 带代次且只能完成一次：旧在途失败不能在新探针成功后又打开熔断。FAILURE 只统计可归因的依赖失败；本地准入拒绝、鉴权或业务冲突用 IGNORED，不算依赖坏了。CLOSED 中成功重置连续失败数。半开探针若不终止会保持拒绝，所以适配器必须有本地结束/收尾路径。多实例各有探针、重启重置状态，全球流量仍靠额外预算与下游准入控制。</p><p>客户端 timeout/cancel 只是停止等待；写入可能已提交，仍是 UNKNOWN。取消持久订单需独立业务命令；A2 已接受的后台履约不因 HTTP 断开就删除。只读重试循环不得复用于扣款。</p>''','''<p>State transitions and clock observations share one lock; I/O stays outside it. Each generation-tagged ticket completes once, so an old failure cannot reopen after a newer successful probe. Count attributable dependency failures only; local denial, authorization and business conflicts are IGNORED. Success in CLOSED resets the consecutive count. A probe that never terminates keeps admission closed, so adapters need local termination/cleanup. Every caller instance has its own probe, and restart resets state; aggregate budgets and downstream admission remain necessary.</p><p>Client timeout/cancel stops waiting but cannot prove a write did not commit: it remains UNKNOWN. Cancel a durable order through a separate business command. A2 background fulfillment survives HTTP disconnect. Never reuse this read retry loop for charging.</p>'''))
replace_content('idempotency',bi('''<p><strong>K 属于业务意图，不属于实例。</strong>作用域是非空、规范化的 tenant / operation / K，客户端重试保持 K 和请求内容；Order 校验当前授权与规范化摘要。同键同摘要回放，同键改内容冲突。唯一组合键由数据库裁决并发，不能“先查没有”后无约束插入；PostgreSQL18 的唯一与 NOT NULL 约束见 <a href="#ref-8">[8]</a>。以下伪码对应图六，完整 schema 用延迟外键把永久 K 映射指向同事务创建的订单。</p>''','''<p><strong>K belongs to intent, not an instance.</strong> Scope nonempty canonical tenant/operation/K; keep K and request content stable. Order checks current authorization and canonical digest. Same key/digest replays, changed content conflicts. Database composite uniqueness arbitrates concurrency; unchecked read-then-insert cannot. PostgreSQL18 documents uniqueness and NOT NULL. <a href="#ref-8">[8]</a> This implements deck six; the full schema uses a deferred foreign key from permanent K mapping to the order created in the same transaction.</p>''')+code('accept.pseudo','Pseudocode · accept','pseudocode')+bi('''<p>READ COMMITTED 下冲突插入可能等首事务结局，随后 SELECT 用新语句快照读已提交结果 <a href="#ref-8">[8]</a>；连接/锁/语句都须限时。首事务未提交且仍在执行时，空查询不证明未执行，返回 UNKNOWN/IN_PROGRESS；回滚确实确认才可同 K 再竞争。commit 后 ACK 丢失，换 B 查同库映射恢复。演示真实 SQLite 的写事务串行化，未声称跑过 PostgreSQL18。</p><p>订单、结果和 outbox 三项同成同败，示例只证明本地订单承诺；Redis 过期锁、本地 Set 或换实例新建键都不够。支付须另传稳定 payment_operation_id，并由支付权威原子防重、可查结果；查询旧订单也须当前对象权限，K 不是凭证。</p><p>A8 七天×1 KB 结果按全天峰值上界：200×86,400=17.28M/天，17.28 GB/天，七天 120.96 GB 逻辑记录，索引/副本/outbox 另算。之后可删大结果，永久保留紧凑 K→order 与原摘要，旧 K 查当前状态；长期映射另估容量。UNKNOWN 不能到期放行。Stripe <strong>API v1</strong> 支持保存首次执行响应与参数比较，但其裁剪后可重新执行，API v2 语义也不同；均不等于本章七天+永久映射政策 <a href="#ref-7">[7]</a>。</p>''','''<p>Under READ COMMITTED, conflicting insert can wait for the first transaction; the following SELECT uses a fresh statement snapshot. <a href="#ref-8">[8]</a> Bound connection/lock/statement waits. An empty query while prior work is unresolved does not prove absence: return UNKNOWN/IN_PROGRESS. Confirmed rollback permits the same K to compete. After commit/ACK loss, B recovers from the shared mapping. The executable adapter checks SQLite serialized writes, not PostgreSQL18 execution.</p><p>Order, result and outbox commit together, proving one local order only. Expiring Redis locks, local sets and new keys after instance changes do not suffice. Payment requires its own stable payment_operation_id and authoritative atomic dedupe/query. Replay still needs current object authorization; K is not a credential.</p><p>A8 at sustained peak gives 200×86,400=17.28M/day, 17.28 GB/day and 120.96 GB for seven days of 1 KB logical records. Indexes/replicas/outbox are separate. Trim large results afterward but permanently retain compact K→order/digest and query current state; size that mapping separately. Never expire UNKNOWN into permission to repeat. Stripe <strong>API v1</strong> stores first execution responses and compares parameters, but permits re-execution after pruning, while API v2 differs. Neither defines this chapter’s seven-day/permanent-mapping policy. <a href="#ref-7">[7]</a></p>'''))
replace_content('release',bi('''<p><strong>先 expand，再灰度，最后 contract。</strong>图七是同一个 Order 的 v1/v2，共用 K 权威与逻辑数据所有者。先加兼容字段与事件合同，再让新意图走 v2；A10 每秒 1,000 个新意图的 10%=100/s，重试按既有 K 固定路由或共享兼容权威恢复，不能把同一个写请求镜像执行两版。此 1,000/s 是独立发布示例，不与订单 A3 的 200/s 混算。渐进替代思路见 Strangler Fig <a href="#ref-10">[10]</a>；真正迁库还需复制、追平屏障与写入所有权切换。</p><p>A9 三台各计划 600/s=1,800/s，排空一台剩 1,200≥1,000；两台起步则只剩 600 不够。这不证明同机/整库故障可扛。READY 之后接流量，排空时先关本地准入、通知路由停止新流量，再有界等待旧请求；路由传播期间仍须本地拒绝。灰度异常停止新分配、回退兼容代码，已提交订单继续按 operation_id 查。等旧实例/读者/回滚窗口/旧事件都安全后才删字段；代码回退不倒转业务状态。</p><p>追踪传播 W3C traceparent 的 trace-id/parent-id <a href="#ref-9">[9]</a>，每 hop 与每 attempt 分 span，业务 K 不变。记录路由版本、实例/版本、剩余时间、重试原因、熔断拒绝、operation_id 和积压年龄，才能分清慢在排队还是下游。trace_id 既不是幂等键，也不是权限证明；外部传入上下文须经过信任边界。</p>''','''<p><strong>Expand, canary, then contract.</strong> Deck seven is v1/v2 of one Order sharing K authority and data ownership. Add compatible fields/events before routing new intents to v2. A10 sends 10% of 1,000 new intents/s=100/s. Recover retries by existing K through pinned routing or compatible shared authority, never mirror one effectful request to both versions. This independent rollout scenario does not reuse A3’s 200/s load. Strangler Fig motivates gradual replacement. <a href="#ref-10">[10]</a> Store migration additionally needs replication, catch-up barriers and write ownership transfer.</p><p>A9 three planned 600/s instances give 1,800/s; draining one leaves 1,200≥1,000. Starting with two leaves only 600. This does not prove colocated-host/store resilience. Admit after READY; drain closes local admission, tells routing to stop intake, then bounds old work. Locally reject during propagation. On canary failure stop new assignments and roll back compatible code; durable orders remain queryable. Remove fields only after old instances/readers, rollback windows and retained events are safe. Code rollback does not reverse business state.</p><p>Propagate W3C traceparent trace-id/parent-id. <a href="#ref-9">[9]</a> Give hops and attempts separate spans while K remains stable. Record route revision, endpoint/version, remaining time, retry reason, breaker rejection, operation_id and backlog age to locate queueing versus downstream delay. A trace ID is neither dedupe identity nor authorization; handle incoming context at the trust boundary.</p>'''))
# Unique follow-ups are merged into the path; remove duplicated summaries/tables.
for marker in ['八个常见翻车点','追问：把答案指回路径']:
    s=re.sub(r'<section><h2><span class="lang-zh">'+marker+r'.*?</section>','',s,flags=re.S)
# Preserve all animation IDs/geometry. Only deck-five wording changes.
s=s.replace('one retry owner · max 2 total attempts','one retry owner · max 2 attempts · recheck before I/O')
s=s.replace('The first attempt has a 220 ms cap including connection and queue costs.','The first attempt has a 220 ms cap including scheduling, discovery, connection and queue costs; the worker rechecks useful remaining time before I/O.')
s=s.replace('No extra service is added; admission checks deadline and retry budget.','No extra service is added. Admission rechecks the same deadline after backoff and worker scheduling, requires 100 ms useful time, preserves 140 ms finish time, and checks shared retry budget and local breaker.')
s=s.replace('先保留 140 ms 完成与回程，再分给第二次 attempt。只有剩余时间够做有用调用、幂等与额外流量预算都通过，才重试。','先保留 140 ms 完成与回程，晚醒/迟调度继续扣时；worker 临发剩余不足教学最小 100 ms 就停止，且须通过共享额外预算与本地熔断。')
s=s.replace('只给读库存的第一次 attempt 220 ms，连接、排队和 RPC 都算在里面。查失败后是否再试，由 Order 统一决策。','第一次只读库存 attempt 最多220ms，调度、发现、连接、排队与RPC共享此帽。worker临发剩余不足教学100ms就停止。')
s=s.replace('The first read-only inventory attempt has a 220 ms cap including connection, queueing and RPC. Order alone decides whether to retry.','The first read-only attempt caps scheduling, discovery, connect, queue and RPC at 220ms. The worker requires at least 100ms useful time before I/O.')
s=s.replace('退避也要付时间。A6 取 40 ms 上限，最多两次总 attempt；网关、代理和 SDK 的自动重试要服从同一个策略。','退避也扣时间：定时目标最多40ms，晚醒再核原死线。最多两次总attempt，Order单一owner，关闭SDK/代理隐藏重试。')
s=s.replace('Backoff consumes time too. A6 caps jitter at 40 ms and permits two total attempts; gateway, proxy and SDK behavior must follow one policy.','Backoff targets at most 40ms; late wakeup rechecks the original deadline. Order owns two total attempts, with hidden SDK/proxy retries disabled.')
s=s.replace('第二次再留 220 ms，并先留出回程预算。200 次/秒原始请求若只有 10% 补一次，额外是 20 次/秒，合计 220 次/秒。','第二次最多220ms，先保留140ms完成回程，实际调度后再核有用时间。A7共享权威每固定秒最多20次额外准入，200+20=220。')
s=s.replace('Reserve another 220 ms only after reserving the reply budget. At 200 originals/s with 10% retried once, add 20 attempts/s for 220 total.','Attempt two gets at most 220ms after preserving 140ms finish/return; recheck after scheduling. A7 shared authority admits at most 20 extras per fixed second: 200+20=220.')
s=s.replace('完整预算 80+220+40+220+140=700 ms，余 100 ms。到点停止新工作并取消下游；取消信号不能撤销已提交的写。','计划阶段帽合计700ms，距800ms留100ms；晚醒/调度可消耗余量，不能硬保端到端延迟。到点停止派发，取消不撤销提交。')
s=s.replace('The full cap is 80+220+40+220+140=700 ms, leaving 100 ms. Stop new work and cancel downstream at expiry; cancellation does not undo committed writes.','Planned caps total 700ms under 800ms; scheduling/late wakeup may spend the 100ms slack. Stop dispatch at expiry; cancellation cannot undo commit or promise hard real-time completion.')
s=s.replace('A6: 80 + 220 + 40 + 220 + 140 = 700 ms &lt; 800 ms; reserve 100 ms','A6: 80 + 220 + 40 + 220 + 140 = 700 ms planned; 100 ms slack')
# Insert a short explicit note after deck-five figure through its nearby prose already above.
# Scope Stripe's product claim and add freshly checked sources.
s=s.replace('核对参数比较与结果保存；七天保留期不引自 Stripe。','仅引用 API v1 的参数比较与保存首响应；裁剪后可重新执行，API v2 不同；七天与永久映射不引自 Stripe。').replace('Checks parameter comparison and saved results; seven-day retention is not a Stripe claim.','API v1 parameter matching/first responses; pruning permits re-execution and v2 differs. Seven days/permanent mapping are local policy.')
s=s.replace('rel_mitigate_interaction_limit_retries.html','rel_mitigate_interaction_failure_limit_retries.html')
refend=s.index('</ol>',s.index('<ol class="references">'))
refs='''<li id="ref-13">[13] AWS Prescriptive Guidance, <a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/circuit-breaker.html">Circuit breaker pattern</a>, living docs, checked 2026-10-24. <span class="lang-zh">反复失败后停止转发与恢复探测；连续3次/冷却1秒/本地代次是本文教学策略。</span><span class="lang-en">Stop forwarding after repeated failures and probe recovery; three failures, one second and local epochs are teaching policy.</span></li>
<li id="ref-14">[14] IETF, <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-15.3.2">RFC 9110 §§15.3.2–15.3.3</a>, 2022, checked 2026-10-24. <span class="lang-zh">201创建资源、202接受但未完成；ACCEPTED/PAID是本章业务合同。</span><span class="lang-en">201 created resources and 202 accepted but incomplete; ACCEPTED/PAID are local business states.</span></li>
'''
s=s[:refend]+refs+s[refend:]
s=s.replace('latest/reliability-pillar/rel_mitigate_interaction_failure_limit_retries.html','latest/framework/rel_mitigate_interaction_failure_limit_retries.html')
s=s.replace('18 · Constraints</a>', '18 · Constraints</a>, <a href="https://www.postgresql.org/docs/18/transaction-iso.html#XACT-READ-COMMITTED">Read Committed</a>, <a href="https://www.postgresql.org/docs/18/sql-createtable.html">CREATE TABLE</a>')
# Date all living-reference checks without claiming a fixed product version.
s=s.replace('在线文档</span><span class="lang-en">living docs</span>)','在线文档</span><span class="lang-en">living docs</span>; checked 2026-10-24)')
# Sync review cards with the stronger admission and version boundary.
s=s.replace('它是 80+220+40+220+140 的阶段预算帽；800 ms 留 100 ms，整体尾部另测。','它是计划阶段帽，留100ms；晚醒/排队仍扣时，worker临发保留140ms且有用时间≥100ms，整体尾部另测。').replace('Stage caps total 700, leaving 100 under 800; measure aggregate tails separately.','Planned caps total 700 with 100 slack; charge late wakes/queues and require ≥100 useful ms plus 140 finish ms before I/O. Measure tails.')
s=s.replace('单 owner，两次总 attempt，额外最多 20/s，合计 220/s。','单 owner、两次总attempt；共享权威每固定秒最多20次额外准入，200+20=220，边界仍可能集中。').replace('Layers multiply attempts. One owner, two total attempts, ≤20 extras/s for 220/s total.','Layers multiply calls. One owner, two total attempts, shared authority admits ≤20 extras per fixed second: 220 total; boundaries may cluster.')
# New breaker card; original twelve retained, one useful question added.
card='''<button type="button" class="flip"><span class="q"><span class="lang-zh">半开为什么只放一个探针？</span><span class="lang-en">Why one half-open probe?</span></span><span class="a"><span class="lang-zh">本地锁一次只准一个；成功关闭，失败再冷却。代次忽略旧完成，多实例仍各有探针。</span><span class="lang-en">A local lock admits one probe; success closes, failure cools again. Epochs ignore stale completion; each process still has a probe.</span></span></button>'''
s=s.replace('</div></section>\n<p class="read-status">',card+'</div></section>\n<p class="read-status">') if '</div></section>\n<p class="read-status">' in s else s
if card not in s:
    at=s.rfind('</div></section>');s=s[:at]+card+s[at:]
# Keep compact conclusion consistent with admission-count semantics.
s=s.replace('额外重试封在 20/s','共享权威把额外准入封在每固定秒20次').replace('cap retries at 20/s','admit at most 20 extras per fixed second through shared authority')
(ROOT/'chapters/ch44.html').write_text(s)
